import{_ as a,o as s,c as i,a2 as e}from"./chunks/framework.BbQrW5_t.js";const k=JSON.parse('{"title":"网络协议","description":"","frontmatter":{"title":"网络协议","date":"2026-09-03T00:00:00.000Z","tags":["网络安全","初级"]},"headers":[],"relativePath":"study/cyber-security/chapters/初级篇/01-网络协议.md","filePath":"study/cyber-security/chapters/初级篇/01-网络协议.md","lastUpdated":1788493831000}'),n={name:"study/cyber-security/chapters/初级篇/01-网络协议.md"};function l(d,t,h,p,r,o){return s(),i("div",null,[...t[0]||(t[0]=[e(`<h1 id="_01-·-网络协议——建立包级别的视野" tabindex="-1">01 · 网络协议——建立包级别的视野 <a class="header-anchor" href="#_01-·-网络协议——建立包级别的视野" aria-label="Permalink to &quot;01 · 网络协议——建立包级别的视野&quot;">​</a></h1><blockquote><p>你写了 20 年代码，一直在&quot;应用层&quot;看世界。安全工作需要你下潜到<strong>包级别</strong>：每一个连接、每一个字节、每一次握手都看得见。这一章是所有后续内容的地基。</p></blockquote><h2 id="🎯-学习目标" tabindex="-1">🎯 学习目标 <a class="header-anchor" href="#🎯-学习目标" aria-label="Permalink to &quot;🎯 学习目标&quot;">​</a></h2><ol><li>不查资料说清 OSI 七层与 TCP/IP 四层的对应关系，以及&quot;每一层攻什么&quot;</li><li>用 Wireshark 抓到并逐包标注一次完整 TCP 握手与挥手</li><li>说清 TLS 握手流程，知道抓包里哪些字段可见、哪些永远不可见</li><li>手动 dig 一个域名，讲清 DNS 递归解析的完整链路</li></ol><h2 id="📖-核心知识" tabindex="-1">📖 核心知识 <a class="header-anchor" href="#📖-核心知识" aria-label="Permalink to &quot;📖 核心知识&quot;">​</a></h2><h3 id="_1-1-双模型对照-每层攻什么" tabindex="-1">1.1 双模型对照：每层攻什么 <a class="header-anchor" href="#_1-1-双模型对照-每层攻什么" aria-label="Permalink to &quot;1.1 双模型对照：每层攻什么&quot;">​</a></h3><table tabindex="0"><thead><tr><th>OSI 层</th><th>TCP/IP 层</th><th>传输单位</th><th>安全攻击面（预告）</th></tr></thead><tbody><tr><td>应用/表示/会话</td><td>应用层</td><td>数据</td><td>SQL 注入、XSS、DNS 隧道</td></tr><tr><td>传输</td><td>传输层</td><td>段/数据报</td><td>端口扫描、SYN Flood、会话劫持</td></tr><tr><td>网络</td><td>网络层</td><td>包</td><td>IP 欺骗、路由劫持、ICMP 隧道</td></tr><tr><td>数据链路/物理</td><td>网络接口层</td><td>帧/比特</td><td>ARP 欺骗、MAC 泛洪、监听</td></tr></tbody></table><blockquote><p>工程师视角：你平时调 API 在第 7 层；nmap 在 4 层干活；ARP 欺骗在 2 层。<strong>层次决定工具与防御位置</strong>。</p></blockquote><h3 id="_1-2-tcp-三次握手-逐包版" tabindex="-1">1.2 TCP 三次握手（逐包版） <a class="header-anchor" href="#_1-2-tcp-三次握手-逐包版" aria-label="Permalink to &quot;1.2 TCP 三次握手（逐包版）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端                     服务端</span></span>
<span class="line"><span>   │ --- SYN (seq=x) -------&gt; │   第1次：我想建立连接（我能发）</span></span>
<span class="line"><span>   │ &lt;-- SYN+ACK (seq=y,ack=x+1) │ 第2次：收到（你能发我能收）</span></span>
<span class="line"><span>   │ --- ACK (ack=y+1) ------&gt; │   第3次：收到（双向确认完成）</span></span></code></pre></div><ul><li>为什么是三次不是两次：防止历史（迟到）的 SYN 建立无效连接——第二次握手本质是&quot;序列号协商&quot;</li><li><strong>Wireshark 过滤器</strong>：<code>tcp.flags.syn==1 &amp;&amp; tcp.flags.ack==0</code>（只看握手的第一个包）；<code>tcp.stream eq 0</code>（追踪某条流）</li></ul><h3 id="_1-3-四次挥手与-time-wait" tabindex="-1">1.3 四次挥手与 TIME_WAIT <a class="header-anchor" href="#_1-3-四次挥手与-time-wait" aria-label="Permalink to &quot;1.3 四次挥手与 TIME_WAIT&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>主动方 --- FIN ---&gt; 被动方    （我不发了）</span></span>
<span class="line"><span>被动方 --- ACK ---&gt; 主动方    （知道了，但我可能还有话说）</span></span>
<span class="line"><span>被动方 --- FIN ---&gt; 主动方    （我说完了）</span></span>
<span class="line"><span>主动方 --- ACK ---&gt; 被动方    （再见）→ 主动方进入 TIME_WAIT(2MSL)</span></span></code></pre></div><p>安全视角：SYN Flood 攻击就是&quot;只做第一次握手&quot;耗尽服务端半连接队列；TIME_WAIT 过多说明本机主动关闭了大量短连接（扫描器的副作用）。</p><h3 id="_1-4-http-细节速查" tabindex="-1">1.4 HTTP 细节速查 <a class="header-anchor" href="#_1-4-http-细节速查" aria-label="Permalink to &quot;1.4 HTTP 细节速查&quot;">​</a></h3><p><strong>方法</strong>：GET / POST / PUT / DELETE / HEAD / OPTIONS / PATCH——OPTIONS 常被用来探测服务器允许的方法（安全测试第一步之一）。</p><p><strong>关键请求头</strong>（安全视角）：</p><table tabindex="0"><thead><tr><th>头</th><th>作用</th><th>攻防意义</th></tr></thead><tbody><tr><td>Host</td><td>虚拟主机路由</td><td>同 IP 多站的&quot;门牌号&quot;</td></tr><tr><td>Cookie</td><td>会话凭证</td><td>窃取目标（XSS 的危害载体）</td></tr><tr><td>Referer</td><td>来源页</td><td>CSRF 防御的弱手段之一</td></tr><tr><td>User-Agent</td><td>客户端标识</td><td>WAF 指纹/爬虫识别</td></tr><tr><td>X-Forwarded-For</td><td>代理链 IP</td><td><strong>可伪造</strong>，服务端常误信</td></tr></tbody></table><p><strong>状态码</strong>：200/301/302/304/403/404/500 常规；安全测试特别关注 302（登录跳转暗示）、403（有资源但被拦——改路径可能绕过）、500（报错泄露栈信息）。</p><h3 id="_1-5-https-tls-握手-抓包能看到什么" tabindex="-1">1.5 HTTPS/TLS 握手：抓包能看到什么 <a class="header-anchor" href="#_1-5-https-tls-握手-抓包能看到什么" aria-label="Permalink to &quot;1.5 HTTPS/TLS 握手：抓包能看到什么&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① ClientHello        → 支持的 TLS 版本/加密套件/随机数/SNI（明文可见！）</span></span>
<span class="line"><span>② ServerHello+证书   → 证书链（明文可见：域名、颁发者、有效期）</span></span>
<span class="line"><span>③ 密钥交换           → ECDHE 参数（明文可见参数，看不见密钥本身）</span></span>
<span class="line"><span>④ ChangeCipherSpec   → 之后所有应用数据都是密文</span></span></code></pre></div><p><strong>核心结论</strong>：TLS 保护的是<strong>应用数据</strong>，但 SNI（你要访问哪个域名）、目标 IP、流量大小与时序<strong>全部明文可见</strong>——这就是&quot;流量分析&quot;永远有效的底层原因，也是后面 DNS 隧道/C2 流量检测的物理基础。</p><p>动手看：Wireshark 过滤器 <code>tls.handshake.type == 1</code>（ClientHello），看 SNI 字段。</p><h3 id="_1-6-dns-解析全链路" tabindex="-1">1.6 DNS 解析全链路 <a class="header-anchor" href="#_1-6-dns-解析全链路" aria-label="Permalink to &quot;1.6 DNS 解析全链路&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +trace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> www.example.com</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 从根服务器开始，完整展示递归链</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> www.example.com</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +short</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 日常用法</span></span></code></pre></div><p>链路：本机缓存 → 本地 DNS（运营商）→ 根 → .com TLD → 权威服务器。安全关联：子域名枚举（第 1 年 W16 的原理）、DNS 劫持、DNS 隧道（高级篇 C2 流量）。</p><h3 id="_1-7-代理-vpn-nat-流量如何被改写" tabindex="-1">1.7 代理 / VPN / NAT：流量如何被改写 <a class="header-anchor" href="#_1-7-代理-vpn-nat-流量如何被改写" aria-label="Permalink to &quot;1.7 代理 / VPN / NAT：流量如何被改写&quot;">​</a></h3><table tabindex="0"><thead><tr><th>技术</th><th>工作层</th><th>改写内容</th><th>安全场景</th></tr></thead><tbody><tr><td>HTTP 代理</td><td>7</td><td>整个请求可见可改</td><td>Burp 的工作模式</td></tr><tr><td>SOCKS 代理</td><td>5</td><td>TCP 连接中转</td><td>扫描器流量出口</td></tr><tr><td>VPN</td><td>3</td><td>整个 IP 包封装</td><td>流量全托管</td></tr><tr><td>NAT</td><td>3</td><td>源 IP:端口重写</td><td>内网共享出口——日志里只见 NAT IP</td></tr></tbody></table><p>Burp 的工作本质：把浏览器流量指向 127.0.0.1:8080，代理程序&quot;中间人&quot;式读写请求（对 HTTPS 需要安装 Burp 证书，原理就是 TLS 中间人——你有了自己的 CA）。</p><h2 id="🔬-动手实操-本地授权环境" tabindex="-1">🔬 动手实操（本地授权环境） <a class="header-anchor" href="#🔬-动手实操-本地授权环境" aria-label="Permalink to &quot;🔬 动手实操（本地授权环境）&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. 抓一次完整握手（终端1）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tcpdump</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> any</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;host example.com and port 443&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. 触发流量（终端2）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://example.com</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. Wireshark 过滤练习</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#    tcp.flags.syn==1 &amp;&amp; tcp.flags.ack==0     → 所有握手第一包</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#    tls.handshake.type == 1                  → 所有 ClientHello</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#    dns.qry.name contains &quot;example&quot;          → DNS 查询</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 4. DNS 递归链</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +trace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> baidu.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -30</span></span></code></pre></div><h2 id="⚠️-常见坑" tabindex="-1">⚠️ 常见坑 <a class="header-anchor" href="#⚠️-常见坑" aria-label="Permalink to &quot;⚠️ 常见坑&quot;">​</a></h2><ol><li><strong>只背模型不抓包</strong>——协议知识必须落在&quot;看见的字节&quot;上才长在身上</li><li>把 HTTPS 当&quot;绝对安全&quot;——SNI/时序/大小全裸奔</li><li>混淆&quot;加密&quot;与&quot;认证&quot;——TLS 两者都做，缺一不可</li><li>忽略 DNS：90% 的攻击链第一步是&quot;找到目标&quot;，而找目标靠 DNS</li><li>在生产环境随意抓包——先确认权限，抓包内容含敏感数据</li></ol><h2 id="✅-自测题" tabindex="-1">✅ 自测题 <a class="header-anchor" href="#✅-自测题" aria-label="Permalink to &quot;✅ 自测题&quot;">​</a></h2><details><summary>1. 为什么 TCP 需要三次握手，两次为什么不行？</summary><p>第二次握手同时承载&quot;服务端的 SYN+对客户端的确认&quot;。若只有两次，服务端无法确认自己的初始序列号被正确接收，历史迟到 SYN 会建立无效连接并占用资源。</p></details><details><summary>2. TLS 握手后，Wireshark 还能看到哪些信息？</summary><p>SNI（ClientHello 中）、源/目的 IP 与端口、TLS 版本与套件、包大小与时间间隔——即元数据。应用内容不可见。</p></details><details><summary>3. X-Forwarded-For 能作为风控依据吗？</summary><p>不能单独作为依据。它是客户端可伪造的头，只有在&quot;每个代理都可信且追加&quot;的前提下，最后一跳才可靠。应结合 TCP 对端 IP。</p></details><details><summary>4. SYN Flood 利用了协议的哪个设计？</summary><p>半连接队列：服务端收到 SYN 后分配资源并等待第三次 ACK，攻击者只发 SYN 不回 ACK，耗尽队列。</p></details><details><summary>5. dig +trace 与 dig +short 的区别？</summary><p>+trace 从根服务器逐级展示完整解析链（学习/排障用）；+short 只给最终结果（日常用）。</p></details><h2 id="🔗-对应周任务与资源" tabindex="-1">🔗 对应周任务与资源 <a class="header-anchor" href="#🔗-对应周任务与资源" aria-label="Permalink to &quot;🔗 对应周任务与资源&quot;">​</a></h2><ul><li>对应计划：<strong>第1年 W01-W04</strong>（<a href="./../../学习计划/第1年-筑基篇.html">学习计划</a>）</li><li>资源：《图解 TCP/IP》第 3-6 章；Wireshark 官方样例抓包库；PortSwigger《HTTP 基础》</li></ul>`,41)])])}const u=a(n,[["render",l]]);export{k as __pageData,u as default};
